### Objective
Build a production-grade Offline-First Task & Project Synchronization manager in Flutter. Demonstrate the Single Source of Truth (SSOT) repository pattern, persistent local caching via Hive, an offline mutation sync queue with automated retry upon network reconnection, and optimistic UI updates with rollback mechanics.

```dart
import 'dart:async';
import 'package:flutter/material.dart';
import 'package:hive_flutter/hive_flutter.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Hive.initFlutter();

  // 1. Initialize local cache boxes
  final taskBox = await Hive.openBox<Map>('tasks_cache');
  final queueBox = await Hive.openBox<Map>('sync_queue');

  // 2. Wire repository with simulated remote API
  final remoteApi = MockTaskRemoteApi();
  final repository = OfflineFirstTaskRepository(
    taskBox: taskBox,
    queueBox: queueBox,
    remoteApi: remoteApi,
  );

  runApp(OfflineFirstApp(repository: repository, remoteApi: remoteApi));
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN MODELS & ENUMS
// ─────────────────────────────────────────────────────────────────────────────

enum SyncStatus { synced, pending, failed }

class TaskItem {
  final String id;
  final String title;
  final bool isCompleted;
  final SyncStatus syncStatus;
  final DateTime updatedAt;

  const TaskItem({
    required this.id,
    required this.title,
    required this.isCompleted,
    required this.syncStatus,
    required this.updatedAt,
  });

  TaskItem copyWith({
    String? title,
    bool? isCompleted,
    SyncStatus? syncStatus,
    DateTime? updatedAt,
  }) {
    return TaskItem(
      id: id,
      title: title ?? this.title,
      isCompleted: isCompleted ?? this.isCompleted,
      syncStatus: syncStatus ?? this.syncStatus,
      updatedAt: updatedAt ?? this.updatedAt,
    );
  }

  Map<String, dynamic> toMap() => {
    'id': id,
    'title': title,
    'isCompleted': isCompleted,
    'syncStatus': syncStatus.name,
    'updatedAt': updatedAt.millisecondsSinceEpoch,
  };

  factory TaskItem.fromMap(Map map) => TaskItem(
    id: map['id'] as String,
    title: map['title'] as String,
    isCompleted: map['isCompleted'] as bool? ?? false,
    syncStatus: SyncStatus.values.firstWhere(
      (e) => e.name == map['syncStatus'],
      orElse: () => SyncStatus.synced,
    ),
    updatedAt: DateTime.fromMillisecondsSinceEpoch(map['updatedAt'] as int),
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. SIMULATED REMOTE API WITH NETWORK TOGGLE
// ─────────────────────────────────────────────────────────────────────────────

class MockTaskRemoteApi {
  bool isOnline = true;

  Future<void> syncTask(TaskItem task) async {
    await Future.delayed(const Duration(milliseconds: 600)); // Network latency
    if (!isOnline) {
      throw const SocketException('Simulated offline network state');
    }
  }
}

class SocketException implements Exception {
  final String message;
  const SocketException(this.message);
  @override
  String toString() => message;
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. OFFLINE-FIRST REPOSITORY (SSOT)
// ─────────────────────────────────────────────────────────────────────────────

class OfflineFirstTaskRepository {
  final Box<Map> _taskBox;
  final Box<Map> _queueBox;
  final MockTaskRemoteApi _remoteApi;

  final _tasksStreamController = StreamController<List<TaskItem>>.broadcast();
  Stream<List<TaskItem>> get tasksStream => _tasksStreamController.stream;

  OfflineFirstTaskRepository({
    required Box<Map> taskBox,
    required Box<Map> queueBox,
    required MockTaskRemoteApi remoteApi,
  })  : _taskBox = taskBox,
        _queueBox = queueBox,
        _remoteApi = remoteApi {
    _emitCurrentLocalState();
    // Seed sample task if empty
    if (_taskBox.isEmpty) {
      final initial = TaskItem(
        id: 'task_01',
        title: 'Architect Offline-First Data Pipeline',
        isCompleted: false,
        syncStatus: SyncStatus.synced,
        updatedAt: DateTime.now(),
      );
      _taskBox.put(initial.id, initial.toMap());
      _emitCurrentLocalState();
    }
  }

  void _emitCurrentLocalState() {
    final tasks = _taskBox.values.map((m) => TaskItem.fromMap(m)).toList();
    tasks.sort((a, b) => b.updatedAt.compareTo(a.updatedAt));
    _tasksStreamController.add(tasks);
  }

  /// Optimistic mutation: Updates local database immediately, then enqueues background sync
  Future<void> toggleTaskStatus(TaskItem task) async {
    final previousState = task;
    final updatedTask = task.copyWith(
      isCompleted: !task.isCompleted,
      syncStatus: SyncStatus.pending,
      updatedAt: DateTime.now(),
    );

    // 1. Write immediately to local database (Zero-latency UI render!)
    await _taskBox.put(updatedTask.id, updatedTask.toMap());
    _emitCurrentLocalState();

    // 2. Persist to offline sync queue
    await _queueBox.put(updatedTask.id, updatedTask.toMap());

    // 3. Attempt background network sync
    _executeBackgroundSync(updatedTask, previousState);
  }

  Future<void> _executeBackgroundSync(TaskItem task, TaskItem previousState) async {
    try {
      await _remoteApi.syncTask(task);

      // Success: Mark synced in local database and remove from queue
      final syncedTask = task.copyWith(syncStatus: SyncStatus.synced);
      await _taskBox.put(syncedTask.id, syncedTask.toMap());
      await _queueBox.delete(task.id);
      _emitCurrentLocalState();
    } catch (e) {
      debugPrint('⚠️ [OFFLINE SYNC] Network unavailable. Task preserved in sync queue.');
      // Kept as pending in queue! UI reflects pending badge without rollback
    }
  }

  /// Process all pending mutations when connectivity returns
  Future<void> processSyncQueue() async {
    if (_queueBox.isEmpty) return;

    debugPrint('🔄 [SYNC QUEUE] Flushing ${_queueBox.length} queued mutations...');

    final queuedEntries = _queueBox.values.toList();
    for (final raw in queuedEntries) {
      final task = TaskItem.fromMap(raw);
      try {
        await _remoteApi.syncTask(task);
        await _queueBox.delete(task.id);

        final synced = task.copyWith(syncStatus: SyncStatus.synced);
        await _taskBox.put(synced.id, synced.toMap());
      } catch (_) {
        break; // Stop if network drops mid-sync
      }
    }
    _emitCurrentLocalState();
  }

  int get pendingSyncCount => _queueBox.length;
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class OfflineFirstApp extends StatelessWidget {
  final OfflineFirstTaskRepository repository;
  final MockTaskRemoteApi remoteApi;

  const OfflineFirstApp({super.key, required this.repository, required this.remoteApi});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Offline-First Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.deepOrange,
        useMaterial3: true,
      ),
      home: TaskSyncDashboard(repository: repository, remoteApi: remoteApi),
    );
  }
}

class TaskSyncDashboard extends StatefulWidget {
  final OfflineFirstTaskRepository repository;
  final MockTaskRemoteApi remoteApi;

  const TaskSyncDashboard({super.key, required this.repository, required this.remoteApi});

  @override
  State<TaskSyncDashboard> createState() => _TaskSyncDashboardState();
}

class _TaskSyncDashboardState extends State<TaskSyncDashboard> {
  @override
  Widget build(BuildContext context) {
    final isOnline = widget.remoteApi.isOnline;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Offline-First Tasks (SSOT)'),
        centerTitle: true,
        actions: [
          // Network Simulation Switch
          Row(
            children: [
              Icon(
                isOnline ? Icons.wifi : Icons.wifi_off_rounded,
                color: isOnline ? Colors.green : Colors.redAccent,
              ),
              Switch(
                value: isOnline,
                onChanged: (val) {
                  setState(() => widget.remoteApi.isOnline = val);
                  if (val) {
                    widget.repository.processSyncQueue().then((_) => setState(() {}));
                  }
                },
              ),
            ],
          ),
        ],
      ),
      body: Column(
        children: [
          _buildConnectivityBanner(isOnline),
          Expanded(
            child: StreamBuilder<List<TaskItem>>(
              stream: widget.repository.tasksStream,
              builder: (context, snapshot) {
                final tasks = snapshot.data ?? [];
                if (tasks.isEmpty) {
                  return const Center(child: Text('No tasks available.'));
                }

                return ListView.separated(
                  padding: const EdgeInsets.all(16),
                  itemCount: tasks.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 10),
                  itemBuilder: (context, index) {
                    final task = tasks[index];

                    return Card(
                      elevation: 1,
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
                      child: ListTile(
                        leading: Checkbox(
                          value: task.isCompleted,
                          onChanged: (_) {
                            widget.repository.toggleTaskStatus(task).then((_) => setState(() {}));
                          },
                        ),
                        title: Text(
                          task.title,
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            decoration: task.isCompleted ? TextDecoration.lineThrough : null,
                          ),
                        ),
                        subtitle: Text(
                          'Updated: ${task.updatedAt.toLocal().toString().split('.')[0]}',
                          style: const TextStyle(fontSize: 11, color: Colors.grey),
                        ),
                        trailing: _buildSyncPill(task.syncStatus),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildConnectivityBanner(bool isOnline) {
    return Container(
      width: double.infinity,
      color: isOnline ? Colors.green.shade50 : Colors.red.shade50,
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Row(
            children: [
              CircleAvatar(
                radius: 4,
                backgroundColor: isOnline ? Colors.green : Colors.redAccent,
              ),
              const SizedBox(width: 8),
              Text(
                isOnline ? 'Online: Live Sync Active' : 'Offline: Saving Locally',
                style: TextStyle(
                  fontWeight: FontWeight.bold,
                  fontSize: 12,
                  color: isOnline ? Colors.green.shade800 : Colors.red.shade800,
                ),
              ),
            ],
          ),
          if (widget.repository.pendingSyncCount > 0)
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
              decoration: BoxDecoration(
                color: Colors.orange.shade100,
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(
                '${widget.repository.pendingSyncCount} Pending Sync',
                style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: Colors.orange.shade900),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildSyncPill(SyncStatus status) {
    final (color, label, icon) = switch (status) {
      SyncStatus.synced => (Colors.green, 'Synced', Icons.cloud_done_rounded),
      SyncStatus.pending => (Colors.orange, 'Queued', Icons.cloud_upload_rounded),
      SyncStatus.failed => (Colors.redAccent, 'Failed', Icons.sync_problem_rounded),
    };

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Icon(icon, size: 16, color: color),
        const SizedBox(width: 4),
        Text(
          label,
          style: TextStyle(color: color, fontSize: 11, fontWeight: FontWeight.bold),
        ),
      ],
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Single Source of Truth (SSOT)**:
   The UI consumes `tasksStream` emitted exclusively from `_taskBox` in Hive. The presentation layer never queries the remote API directly; it interacts solely with the repository.
2. **Instant Optimistic Local Writes**:
   When `toggleTaskStatus()` is called, it mutates the local Hive database in < 2ms and emits the updated state to the UI. The user sees an immediate checkbox toggle with zero perceived network latency.
3. **Persistent Sync Queue**:
   The mutation is recorded in `_queueBox`. Even if the user terminates the app or power is lost while offline, the action remains stored on disk.
4. **Automated Recovery on Reconnection**:
   When the online switch toggles back to `true`, `processSyncQueue()` iterates through all queued mutations, synchronizes them with the remote backend, and marks them `SyncStatus.synced`.
